-- =============================================
-- 1. STORES TABLE
-- =============================================
CREATE TABLE IF NOT EXISTS stores (
  id          uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  kode        text UNIQUE NOT NULL,
  nama        text NOT NULL,
  branch      text NOT NULL,
  wilayah_bmt text,
  nama_bmt    text,
  nik_bmt     text,
  nik_bmr     text,
  wilayah_bmc text,
  nama_coordinator text,
  nik_coordinator  text,
  created_at  timestamptz DEFAULT now()
);

-- =============================================
-- 2. FCPT SUBMISSIONS TABLE
-- =============================================
CREATE TABLE IF NOT EXISTS fcpt_submissions (
  id          uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  store_kode  text REFERENCES stores(kode),
  submitted_by uuid REFERENCES auth.users(id),
  submitted_at timestamptz DEFAULT now(),
  periode     text,
  status      text DEFAULT 'submitted'
);

-- =============================================
-- 3. FCPT ITEM DETAILS TABLE
-- =============================================
CREATE TABLE IF NOT EXISTS fcpt_item_details (
  id              uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  submission_id   uuid REFERENCES fcpt_submissions(id) ON DELETE CASCADE,
  item_id         text NOT NULL,    -- e.g. A1, B2, C3
  kondisi         text,             -- BAIK / RUSAK MASIH DAPAT DIGUNAKAN / RUSAK TIDAK DAPAT DIGUNAKAN
  nilai           int,              -- slider value
  keterangan      text,
  foto_url        text,
  created_at      timestamptz DEFAULT now()
);

-- =============================================
-- 4. RLS POLICIES
-- =============================================
ALTER TABLE stores ENABLE ROW LEVEL SECURITY;
ALTER TABLE fcpt_submissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE fcpt_item_details ENABLE ROW LEVEL SECURITY;

CREATE POLICY "stores readable by all authenticated" ON stores FOR SELECT TO authenticated USING (true);
CREATE POLICY "fcpt_submissions insertable" ON fcpt_submissions FOR INSERT TO authenticated WITH CHECK (true);
CREATE POLICY "fcpt_submissions readable" ON fcpt_submissions FOR SELECT TO authenticated USING (true);
CREATE POLICY "fcpt_item_details insertable" ON fcpt_item_details FOR INSERT TO authenticated WITH CHECK (true);
CREATE POLICY "fcpt_item_details readable" ON fcpt_item_details FOR SELECT TO authenticated USING (true);

-- =============================================
-- 5. SEED STORES DATA
-- =============================================
ON CONFLICT (kode) DO NOTHING;